using namespace std;
#include <iostream>
#include <stack>
#include <string>

class Transaction {
  public:
    string sender;
    string receiver;
    double amount;
    Transaction(string sender, string receiver, double amount) {
        this->sender = sender;
        this->receiver = receiver;
        this->amount = amount;
    }
};

class Wallet {
  private:
    stack<Transaction> transactions;

  public:
    void addTransaction(Transaction transaction) {
        transactions.push(transaction);
    }
    Transaction getLatestTransaction() {
        Transaction latestTransaction = transactions.top();
        transactions.pop();
        return latestTransaction;
    }
};

int main() {
    Wallet wallet;
    wallet.addTransaction(Transaction("Alice", "Bob", 10.0));
    Transaction latestTransaction = wallet.getLatestTransaction();
    wallet.addTransaction(Transaction("Charlie", "David", 20.0));
    cout << latestTransaction.sender << " sent "
              << latestTransaction.amount << " to "
              << latestTransaction.receiver << endl;
    return 0;
}

#include <iostream>
#include <string>

class BankAccount {
  private:
    std::string accountHolder;
    double balance;
    int transactionCount;
    double transactions[10];

  public:
    BankAccount(std::string accountHolder, double initialBalance)
        : accountHolder(accountHolder), balance(initialBalance),
          transactionCount(0) {
    }

    void deposit(double amount) {
        balance += amount;
        transactions[transactionCount] = amount;
        transactionCount++;
    }

    void displayTransactions() {
        for (int i = 0; i <= transactionCount; i++) {
            std::cout << "Transaction " << i << ": " << transactions[i]
                      << std::endl;
        }
    }
};

int main() {
    BankAccount account("John Doe", 1000.0);
    account.deposit(500.0);
    account.deposit(200.0);
    account.displayTransactions();
    return 0;
}

