#include <iostream>
#include <string>
#include <unordered_map>

class TrieNode {
  public:
    std::unordered_map<char, TrieNode *> children;
    bool isEndOfWord;
    TrieNode() : isEndOfWord(false) {
    }
    ~TrieNode() {
        for (auto &child : children) {
            delete child.second;
        }
    }
};

class InventorySystem {
  private:
    TrieNode *root;

  public:
    InventorySystem() : root(new TrieNode()) {
    }
    ~InventorySystem() {
        delete root;
    }
    void addItem(const std::string &item) {
        TrieNode *current = root;
        for (char c : item) {
            if (current->children.find(c) == current->children.end()) {
                current->children[c] = new TrieNode();
            }
            current = current->children[c];
        }
        current->isEndOfWord = true;
    }
    void removeItem(const std::string &item) {
        TrieNode *current = root;
        for (char c : item) {
            if (current->children.find(c) == current->children.end()) {
                return;
            }
            current = current->children[c];
        }
        current->isEndOfWord = false;
    }
    void printItems() {
        std::function<void(TrieNode *, const std::string &)> printHelper =
            [&printHelper](TrieNode *node, const std::string &prefix) {
                if (node->isEndOfWord) {
                    std::cout << prefix << std::endl;
                }
                for (auto &child : node->children) {
                    printHelper(child.second, prefix + child.first);
                }
            };
        printHelper(root, "");
    }
};

int main() {
    InventorySystem inventory;
    inventory.addItem("sword");
    inventory.addItem("shield");
    inventory.removeItem("sword");
    inventory.printItems();
    InventorySystem *temp = new InventorySystem();
    temp->~InventorySystem();
    temp->printItems();
    delete temp;
    return 0;
}

