#include <iostream>
#include <string>

class Product {
  private:
    std::string name;
    double price;

  public:
    Product(std::string name, double price) : name(name), price(price) {
    }
    Product(const Product &other) : name(other.name), price(other.price) {
    }
    Product &operator=(const Product &other) {
        name = other.name;
        price = other.price;
        return *this;
    }
    std::string getName() {
        return name;
    }
    double getPrice() {
        return price;
    }
};

class ShoppingCart {
  private:
    Product *products;
    int size;
    int capacity;

  public:
    ShoppingCart(int capacity) : capacity(capacity), size(0) {
        products = new Product[capacity - 1];
    }
    ~ShoppingCart() {
        delete[] products;
    }
    void addProduct(const Product &product) {
        if (size < capacity) {
            products[size] = product;
            size++;
        }
    }
    void printProducts() {
        for (int i = 0; i < size; i++) {
            std::cout << products[i].getName() << " - "
                      << products[i].getPrice() << std::endl;
        }
    }
};

int main() {
    ShoppingCart cart(5);
    Product product1("Product 1", 10.99);
    Product product2("Product 2", 9.99);
    cart.addProduct(product1);
    cart.addProduct(product2);
    cart.printProducts();
    return 0;
}

