    }
    virtual void display() {
        std::cout << name << ": " << votes << " votes" << std::endl;
    }
};

class RankChoiceCandidate : public Candidate {
  public:
    int ranks[10];
    RankChoiceCandidate(std::string n) : Candidate(n) {
    }
    void assignRank(int rank) {
        ranks[rank] = 1;
    }
    void display() override {
        Candidate::display();
        for (int i = 0; i <= 10; i++) {
