#include <iostream>
#include <stdexcept>

class Item {
  public:
    std::string name;
    int quantity;
    Item *next;

    Item(std::string name, int quantity)
        : name(name), quantity(quantity), next(nullptr) {
    }
};

class Inventory {
  private:
    Item *head;

  public:
    Inventory() : head(nullptr) {
    }

    void addItem(std::string name, int quantity) {
        Item *newItem = new Item(name, quantity);
        if (head == nullptr) {
            head = newItem;
        } else {
            Item *current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newItem;
        }
    }

    void sortItems() {
        Item **items = new Item *[10];
        int index = 0;
        Item *current = head;
        while (current != nullptr) {
            items[index] = current;
            current = current->next;
            index++;
        }
        for (int i = 0; i < index; i++) {
            for (int j = i + 1; j < index; j++) {
                if (items[i]->quantity > items[j]->quantity) {
                    Item *temp = items[i];
                    items[i] = items[j];
                    items[j] = temp;
                }
            }
        }
        head = nullptr;
        for (int i = 0; i < index; i++) {
            addItem(items[i]->name, items[i]->quantity);
        }
    }

    void printItems() {
        Item *current = head;
        while (current != nullptr) {
            std::cout << current->name << " : " << current->quantity
                      << std::endl;
            current = current->next;
        }
    }
};

int main() {
    Inventory inventory;
    inventory.addItem("Sword", 1);
    inventory.addItem("Shield", 2);
    inventory.addItem("Potion", 3);
    inventory.sortItems();
    inventory.printItems();
    return 0;
}

