#include <iostream>
using namespace std;


class Node {
  public:
    int data;
    Node *next;
    Node(int value) {
        data = value;
        next = nullptr;
    }
};

class LinkedList {
  public:
    Node *head;
    LinkedList() {
        head = nullptr;
    }
    void insert(int value) {
        Node *newNode = new Node(value);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node *temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
    void printList() {
        Node *temp = head;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }
};

int main() {
    LinkedList list;
    for (int i = 0; i < 10; i++) {
        list.insert(i);
    }
    list.printList();
    return 0;
}
