#include <iostream>
#include <string>
using std::cout;
using std::endl;
using std::string;

struct Flight {
    string flightNumber;
    string departure;
    string arrival;
    int numberOfPassengers;
};

struct HashNode {
    Flight flight;
    HashNode *next;
};

class HashTable {
  private:
    static const int size = 10;
    HashNode *table[size];

  public:
    HashTable() {
        for (int i = 0; i < size; i++) {
            table[i] = nullptr;
        }
    }

    void insert(const Flight &flight) {
        int index = std::hash<string>{}(flight.flightNumber) % size;
        if (table[index] == nullptr) {
            table[index] = new HashNode{flight, nullptr};
        } else {
            HashNode *node = table[index];
            while (node->next != nullptr) {
                node = node->next;
            }
            node->next = new HashNode{flight, nullptr};
        }
    }

    void print() {
        for (int i = 0; i < size; i++) {
            HashNode *node = table[i];
            while (node != nullptr) {
                cout << "Flight Number: %s, Departure: %s, Arrival: %s, Number "
                        "of Passengers: %d\n",
                    node->flight.flightNumber.c_str(),
                    node->flight.departure.c_str(),
                    node->flight.arrival.c_str(),
                    node->flight.numberOfPassengers;
                node = node->next;
            }
        }
    }
};

int main() {
    HashTable hashTable;
    Flight flight1 = {"AA101", "New York", "Los Angeles", 200};
    Flight flight2 = {"AA102", "Chicago", "New York", 150};
    hashTable.insert(flight1);
    hashTable.insert(flight2);
    hashTable.print();
    return 0;
}

