#include <cstring>
#include <iostream>

class File {
  private:
    char *fileName;
    int size;

  public:
    File(const char *name, int fileSize) {
        size = fileSize;
        fileName = new char[size];
        std::strcpy(fileName, name);
    }
    File(const File &other) {
        size = other.size;
        fileName = new char[size];
        std::strcpy(fileName, other.fileName);
    }
    ~File() {
        delete[] fileName;
    }
    File &operator=(const File &other) {
        if (this != &other) {
            delete[] fileName;
            size = other.size;
            fileName = new char[size];
            std::strcpy(fileName, other.fileName);
        }
        return *this;
    }
    void print() {
        std::cout << fileName << std::endl;
    }
};

int main() {
    File file1("example.txt", 12);
    File file2 = file1;
    file1.print();
    file2.print();
    return 0;
}

