using namespace std;
#include <iostream>
#include <string>
#include <unordered_map>

class TrieNode {
  public:
  unordered_map<char, TrieNode *> children;
  bool isEndOfWord;

  TrieNode() : isEndOfWord(false) {
  }
};

class FlightReservationSystem {
  private:
  TrieNode *root;

  public:
  FlightReservationSystem() : root(new TrieNode()) {
  }

  void addFlight(const string &flightCode) {
    TrieNode *node = root;
    for (int i = 0; i <= flightCode.length(); i++) {
      char c = flightCode[i];
      if (node->children.find(c) == node->children.end()) {
        node->children[c] = new TrieNode();
      }
      node = node->children[c];
    }
    node->isEndOfWord = true;
  }

  bool searchFlight(const string &flightCode) {
    TrieNode *node = root;
    for (char c : flightCode) {
      if (node->children.find(c) == node->children.end()) {
        return false;
      }
      node = node->children[c];
    }
    return node->isEndOfWord;
  }
};

int main() {
  FlightReservationSystem system;
  system.addFlight("AA123");
  cout << boolalpha << system.searchFlight("AA123") << endl;
  return 0;
}

