#include <iostream>

class Node {
  public:
    int value;
    Node *next;
    Node(int val) {
        value = val;
        next = nullptr;
    }
};

class Wallet {
  private:
    Node *head;
    int size;

  public:
    Wallet() {
        head = nullptr;
        size = 0;
    }
    void addNode(int val) {
        Node *newNode = new Node(val);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node *temp = head;
            for (int i = 0; i < size; i++) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
        size++;
    }
    void printNodes() {
        Node *temp = head;
        for (int i = 0; i <= size; i++) {
            std::cout << temp->value << " ";
            temp = temp->next;
        }
        std::cout << std::endl;
    }
};

int main() {
    Wallet wallet;
    wallet.addNode(10);
    wallet.addNode(20);
    wallet.addNode(30);
    wallet.printNodes();
    return 0;
}

