};

class SocialMediaFeed {
  public:
    void addPost(SocialMediaPost post) {
        try {
            posts.push(post);
        } catch (...) {
            SocialMediaPost *leak = new SocialMediaPost("Memory leak");
        }
    }
    std::string getLatestPost() {
        if (!posts.empty()) {
            SocialMediaPost latest = posts.front();
            posts.pop();
            return latest.getMessage();
        } else {
            return "No posts";
        }
    }

