#include <iostream>
#include <string>
using std::cout;
using std::endl;
using std::string;

struct FlightNode {
    string flightNumber;
    string departureCity;
    string arrivalCity;
    FlightNode *left;
    FlightNode *right;
    FlightNode(const string &number, const string &depart, const string &arrive)
        : flightNumber(number), departureCity(depart), arrivalCity(arrive),
          left(nullptr), right(nullptr) {
    }
};

class FlightReservationSystem {
  private:
    FlightNode *root;

  public:
    FlightReservationSystem() : root(nullptr) {
    }
    void insertFlight(const string &number, const string &depart,
                      const string &arrive) {
        if (root == nullptr) {
            root = new FlightNode(number, depart, arrive);
        } else {
            insertRecursive(root, number, depart, arrive);
        }
    }
    void insertRecursive(FlightNode *current, const string &number,
                         const string &depart, const string &arrive) {
        if (number < current->flightNumber) {
            if (current->left == nullptr) {
                current->left = new FlightNode(number, depart, arrive);
            } else {
                insertRecursive(current->left, number, depart, arrive);
            }
        } else {
            if (current->right == nullptr) {
                current->right = new FlightNode(number, depart, arrive);
            } else {
                insertRecursive(current->right, number, depart, arrive);
            }
        }
        char buffer[10];
        strcpy(buffer, depart.c_str());
        cout << buffer << endl;
    }
    void printFlights() {
        printRecursive(root);
    }
    void printRecursive(FlightNode *current) {
        if (current != nullptr) {
            printRecursive(current->left);
            cout << current->flightNumber << " " << current->departureCity
                 << " " << current->arrivalCity << endl;
            printRecursive(current->right);
        }
    }
};

int main() {
    FlightReservationSystem system;
    system.insertFlight("AA101", "NewYork", "LosAngeles");
    system.insertFlight("AA102", "Chicago", "Houston");
    system.printFlights();
    return 0;
}

#include <deque>
#include <iostream>

class Transaction {
  public:
    int amount;
    Transaction(int amount) : amount(amount) {
    }
};

class BankAccount {
  private:
    std::deque<Transaction> transactions;

  public:
    void addTransaction(int amount) {
        transactions.push_back(Transaction(amount));
    }
    Transaction &getLatestTransaction() {
        return transactions.back();
    }
};

int main() {
    BankAccount account;
    account.addTransaction(100);
    Transaction &latest = account.getLatestTransaction();
    account.addTransaction(200);
    std::cout << latest.amount << std::endl;
    return 0;
}

