#include <iostream>
#include <string>
using std::cout;
using std::endl;
using std::string;

struct Node {
    int candidateId;
    string candidateName;
    Node *left;
    Node *right;
};

Node *insertNode(Node *root, int candidateId, string candidateName) {
    if (root == nullptr) {
        Node *newNode = new Node();
        newNode->candidateId = candidateId;
        newNode->candidateName = candidateName;
        newNode->left = nullptr;
        newNode->right = nullptr;
        return newNode;
    }
    if (candidateId < root->candidateId) {
        root->left = insertNode(root->left, candidateId, candidateName);
    } else if (candidateId > root->candidateId) {
        root->right = insertNode(root->right, candidateId, candidateName);
    }
    return root;
}

void printInorder(Node *root) {
    if (root != nullptr) {
        printInorder(root->left);
        cout << "Candidate ID: %s, Candidate Name: %s\n"
             << root->candidateId << root->candidateName;
        printInorder(root->right);
    }
}

int main() {
    Node *root = nullptr;
    root = insertNode(root, 1, "John");
    root = insertNode(root, 2, "Alice");
    root = insertNode(root, 3, "Bob");
    printInorder(root);
    return 0;
}

