#include <iostream>
using namespace std;

#include <string>

struct Node {
    string key;
    int value;
    Node *left;
    Node *right;

    Node(const string &k, int v)
        : key(k), value(v), left(nullptr), right(nullptr) {
    }
};

class Wallet {
  private:
    Node *root;

  public:
    Wallet() : root(nullptr) {
    }

    void insertNode(const string &key, int value) {
        Node *newNode = new Node(key, value);
        if (root == nullptr) {
            root = newNode;
        } else {
            insertNodeRecursive(root, newNode);
        }
    }

    void insertNodeRecursive(Node *current, Node *newNode) {
        if (newNode->key < current->key) {
            if (current->left == nullptr) {
                current->left = newNode;
            } else {
                insertNodeRecursive(current->left, newNode);
            }
        } else {
            if (current->right == nullptr) {
                current->right = newNode;
            } else {
                insertNodeRecursive(current->right, newNode);
            }
        }
    }

    void printInOrder() {
        printInOrderRecursive(root);
    }

    void printInOrderRecursive(Node *current) {
        if (current != nullptr) {
            printInOrderRecursive(current->left);
            cout << current->key << ": " << current->value << endl;
            printInOrderRecursive(current->right);
        }
    }
};

int main() {
    Wallet wallet;
    wallet.insertNode("Bitcoin", 100);
    wallet.insertNode("Ethereum", 50);
    wallet.insertNode("Litecoin", 200);
    wallet.printInOrder();
    return 0;
}
