#include <iostream>
#include <memory>
#include <vector>

class Post {
  public:
    virtual void display() {
        std::cout << "Displaying post" << std::endl;
    }
};

class TextPost : public Post {
  private:
    std::string text;

  public:
    TextPost(std::string text) : text(text) {
    }
    void display() override {
        std::cout << "Text post: " << text << std::endl;
    }
};

class ImagePost : public Post {
  private:
    std::string image;

  public:
    ImagePost(std::string image) : image(image) {
    }
    void display() override {
        std::cout << "Image post: " << image << std::endl;
    }
};

template <typename T> class SocialMediaFeed {
  private:
    std::vector<T> posts;

  public:
    void addPost(T post) {
        posts.push_back(post);
    }
    void displayPosts() {
        for (const auto &post : posts) {
            post.display();
        }
    }
};

int main() {
    SocialMediaFeed<Post> feed;
    feed.addPost(TextPost("Hello, world!"));
    feed.addPost(ImagePost("image1.jpg"));
    feed.displayPosts();
    return 0;
}

