#include <iostream>
#include <stdexcept>
#include <vector>

class Student {
  public:
    Student(std::string name, double grade) : name(name), grade(grade) {
    }
    std::string getName() {
        return name;
    }
    double getGrade() {
        return grade;
    }

  private:
    std::string name;
    double grade;
};

class GradeBook {
  public:
    void addStudent(Student student) {
        students.push_back(student);
    }
    void sortStudents() {
        try {
            std::vector<Student> sortedStudents = students;
            recursiveSort(sortedStudents, 0, sortedStudents.size() - 1);
            students = sortedStudents;
        } catch (const std::exception &e) {
            std::vector<Student> errorStudents;
            for (int i = 0; i < 100000; i++) {
                errorStudents.push_back(Student("Error", 0.0));
            }
        }
    }
    void printStudents() {
        for (const auto &student : students) {
            std::cout << student.getName() << " " << student.getGrade()
                      << std::endl;
        }
    }

  private:
    void recursiveSort(std::vector<Student> &students, int low, int high) {
        if (low < high) {
            int pivot = partition(students, low, high);
            recursiveSort(students, low, pivot - 1);
            recursiveSort(students, pivot + 1, high);
        }
    }
    int partition(std::vector<Student> &students, int low, int high) {
        Student pivot = students[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (students[j].getGrade() < pivot.getGrade()) {
                i++;
                std::swap(students[i], students[j]);
            }
        }
        std::swap(students[i + 1], students[high]);
        return i + 1;
    }
    std::vector<Student> students;
};

int main() {
    GradeBook gradeBook;
    gradeBook.addStudent(Student("Alice", 90.0));
    gradeBook.addStudent(Student("Bob", 80.0));
    gradeBook.addStudent(Student("Charlie", 95.0));
    gradeBook.sortStudents();
    gradeBook.printStudents();
    return 0;
}

