class Account {
  public:
    Account(int balance) : balance_(balance) {
    }
    virtual void deposit(int amount) {
        balance_ += amount;
    }
    virtual void displayBalance() {
        std::cout << "Balance: " << balance_ << std::endl;
    }

  protected:
    int balance_;
};

class SavingsAccount : public Account {
  public:
    SavingsAccount(int balance, int interestRate)
        : Account(balance), interestRate_(interestRate) {
    }
    void deposit(int amount) {
        Account::deposit(amount);
        balance_ += interestRate_;
    }
    void displayBalance() {
        Account::displayBalance();
    }

  private:
    int interestRate_;
};

int main() {
    Account account(1000);
    SavingsAccount savingsAccount(1000, 50);
    Account *accountPtr = &savingsAccount;
    accountPtr->deposit(500);
    accountPtr->displayBalance();
    return 0;
}

