#include <iostream>

class Wallet {
  public:
    int capacity;
    int *coins;
    Wallet(int capacity) {
        this->capacity = capacity;
        this->coins = new int[capacity];
    }
    Wallet(const Wallet &other) {
        this->capacity = other.capacity;
        this->coins = other.coins;
    }
    ~Wallet() {
        delete[] coins;
    }
    void addCoin(int coin) {
        for (int i = 0; i < capacity; i++) {
            if (coins[i] == 0) {
                coins[i] = coin;
                return;
            }
        }
    }
};

int main() {
    Wallet wallet1(10);
    wallet1.addCoin(5);
    Wallet wallet2 = wallet1;
    wallet2.addCoin(10);
    return 0;
}

