#include <cstring>
#include <iostream>

class Candidate {
  private:
    char name[20];
    int votes;

  public:
    Candidate() : votes(0) {
    }
    Candidate(const char *getName) {
        strcpy(name, getName);
        votes = 0;
    }
    void operator+(int numVotes) {
        votes += numVotes;
    }
    void print() {
        std::cout << name << " has " << votes << " votes." << std::endl;
    }
};

class VotingSystem {
  private:
    Candidate candidates[5];
    int numCandidates;

  public:
    VotingSystem() : numCandidates(0) {
    }
    void addCandidate(const char *getName) {
        candidates[numCandidates] = Candidate(getName);
        numCandidates++;
    }
    void printResults() {
        for (int i = 0; i < numCandidates; i++) {
            candidates[i].print();
        }
    }
};

int main() {
    VotingSystem vs;
    vs.addCandidate("John Doe");
    vs.addCandidate("Jane Smith");
    vs.addCandidate("Bob Johnson");
    vs.addCandidate("Alice Brown");
    vs.addCandidate("Mike Davis");
    vs.addCandidate("Emily Taylor");
    vs.printResults();
    return 0;
}

#include <iostream>
#include <memory>
#include <vector>

template <typename T> class ShoppingCart {
  private:
    std::vector<std::unique_ptr<T>> items;

  public:
    void addItem(std::unique_ptr<T> item) {
        items.push_back(std::move(item));
    }
    T &getItem(int index) {
        return *items[index];
    }
};

class Product {
  public:
    Product(std::string name) : name(name) {
    }
    std::string name;
};

int main() {
    ShoppingCart<Product> cart;
    cart.addItem(std::make_unique<Product>("Product1"));
    Product &product = cart.getItem(0);
    cart.addItem(std::make_unique<Product>("Product2"));
    std::cout << product.name << std::endl;
    return 0;
}

