#include <iostream>
#include <string>
using std::cout;
using std::endl;
using std::string;

class Student {
  public:
    string name;
    int grade;
    Student *next;
    Student(string name, int grade) {
        this->name = name;
        this->grade = grade;
        this->next = nullptr;
    }
};

class StudentGradingSystem {
  private:
    Student *head;

  public:
    void addStudent(string name, int grade) {
        Student *newStudent = new Student(name, grade);
        if (head == nullptr) {
            head = newStudent;
        } else {
            Student *current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newStudent;
        }
    }
    void printStudents() {
        Student *current = head;
        while (current != nullptr) {
            cout << current->name << ": " << current->grade << endl;
            current = current->next;
        }
    }
    string getStudentName(int index) {
        Student *current = head;
        int currentIndex = 0;
        while (current != nullptr) {
            if (currentIndex == index) {
                return current->name;
            }
            current = current->next;
            currentIndex++;
        }
        return "";
    }
};

int main() {
    StudentGradingSystem system;
    system.addStudent("John", 90);
    system.addStudent("Alice", 95);
    system.printStudents();
    string name = system.getStudentName(2);
    cout << name << endl;
    return 0;
}

