struct Node {
    int flightNumber;
    Node *next;
};

Node *head = NULL;

void addFlight(int flightNumber) {
    Node *newNode = new Node;
    newNode->flightNumber = flightNumber;
    if (head == NULL) {
        head = newNode;
    } else {
        Node *temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void printFlights() {
    Node *temp = head;
    while (temp != NULL) {
        std::cout << temp->flightNumber << std::endl;
        temp = temp->next;
    }
}

int main() {
    int flightNumbers[] = {101, 102, 103, 104, 105};
    for (int i = 0; i < 5; i++) {
        addFlight(flightNumbers[i]);
    }
    printFlights();
    return 0;
}

