// Example of a LibraryItem class
class LibraryItem {
  public:
    LibraryItem(const std::string &name) : name_(name), borrowed_(false) {
    }
    LibraryItem(const LibraryItem &other)
        : name_(other.name_), borrowed_(other.borrowed_) {
    }
    LibraryItem &operator=(const LibraryItem &other) {
        name_ = other.name_;
        borrowed_ = other.borrowed_;
        return *this;
    }
    void borrow() {
        borrowed_ = true;
    }
    void returnItem() {
        borrowed_ = false;
    }

  private:
    std::string name_;
    bool borrowed_;
};

