  public:
    CompressedFile(const std::vector<T> &data) : data_(new T[data.size()]) {
        for (size_t i = 0; i < data.size(); i++) {
            data_[i] = data[i];
        }
    }
    ~CompressedFile() {
        delete[] data_;
    }
    const T &operator[](size_t index) const {
        return data_[index];
    }

