std::vector<int> walletBalances = {10, 5, 8, 12};

// sorting function using recursion
void sortWalletBalances(std::vector<int> &balances, int start, int end) {
    if (start < end) {
        int pivotIndex = partition(balances, start, end);
        sortWalletBalances(balances, start, pivotIndex - 1);
        sortWalletBalances(balances, pivotIndex + 1, end);
    }
}

// Partition function for quicksort
int partition(std::vector<int> &balances, int start, int end) {
    int pivot = balances[end];
    int i = start - 1;
    for (int j = start; j <= end; j++) {
        if (balances[j] < pivot) {
            i++;
            std::swap(balances[i], balances[j]);
        }
    }
    std::swap(balances[i + 1], balances[end]);
    return i + 1;
}

// Trigger the sorting function
sortWalletBalances(walletBalances, 0, walletBalances.size());

// Print the sorted wallet balances
for (int balance : walletBalances) {
    std::cout << balance << " ";
}

