};
class FlightReservationSystem {
  public:
    FlightNode *root;
    FlightReservationSystem() {
        root = nullptr;
    }
    void insertFlight(int num) {
        if (root == nullptr) {
            root = new FlightNode(num);
        } else {
            insertRecursive(root, num);
        }
    }
    void insertRecursive(FlightNode *current, int num) {
        if (num < current->flightNumber) {
            if (current->left == nullptr) {
                FlightNode node(num);
                current->left = &node;
            } else {
                insertRecursive(current->left, num);
            }
        } else {
            if (current->right == nullptr) {
                FlightNode node(num);
                current->right = &node;
            } else {
                insertRecursive(current->right, num);
            }
        }
    }
};

