// Example library catalog sorting function with a bug
void sortCatalog(int bookIds[], int size) {
    if (size <= 1) {
        return;
    }
    int pivot = bookIds[0];
    int leftSize = 0;
    for (int i = 1; i <= size; i++) {
        if (bookIds[i] < pivot) {
            leftSize++;
        }
    }
    int *left = new int[leftSize];
    int *right = new int[size - leftSize - 1];
    int leftIndex = 0;
    int rightIndex = 0;
    for (int i = 1; i < size; i++) {
        if (bookIds[i] < pivot) {
            left[leftIndex++] = bookIds[i];
        } else if (bookIds[i] > pivot) {
            right[rightIndex++] = bookIds[i];
        }
    }
    sortCatalog(left, leftSize);
    sortCatalog(right, size - leftSize - 1);
    for (int i = 0; i < size; i++) {
        if (i < leftSize) {
            bookIds[i] = left[i];
        } else if (i == leftSize) {
            bookIds[i] = pivot;
        } else {
            bookIds[i] = right[i - leftSize - 1];
        }
    }
    delete[] left;
    delete[] right;
}
int main() {
    int bookIds[] = {5, 2, 8, 3, 1, 4, 6, 7};
    int size = sizeof(bookIds) / sizeof(bookIds[0]);
    sortCatalog(bookIds, size);
    for (int i = 0; i < size; i++) {
        std::cout << bookIds[i] << " ";
    }
    return 0;
}

