// Node class representing an item in the shopping cart
class Node {
  public:
    int item;
    Node *next;
    Node(int item) : item(item), next(nullptr) {
    }
};

// ShoppingCart class managing the linked list of items
class ShoppingCart {
  private:
    Node *head;

  public:
    ShoppingCart() : head(nullptr) {
    }
    // Copy constructor with shallow copy
    ShoppingCart(const ShoppingCart &other) : head(other.head) {
    }
    void addItem(int item) {
        Node *newNode = new Node(item);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node *current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newNode;
        }
    }
    void printItems() {
        Node *current = head;
        while (current != nullptr) {
            std::cout << current->item << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
    ~ShoppingCart() {
        Node *current = head;
        while (current != nullptr) {
            Node *next = current->next;
            delete current;
            current = next;
        }
    }
};

// Example usage
int main() {
    ShoppingCart cart1;
    cart1.addItem(1);
    cart1.addItem(2);
    ShoppingCart cart2 = cart1; // Shallow copy
    cart1.printItems();
    cart2.printItems();
    return 0;
}
